set-header.value:
@{
          var tenantId   = "{{tenant-id}}";
          var clientId   = "{{apim-app-client-id}}";
          var host       = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
          var redirectUri = System.Uri.EscapeDataString(host + "/callback");
          var scope = System.Uri.EscapeDataString(
            "499b84ac-1321-427f-aa17-267ca6975798/user_impersonation openid profile"
          );
          return "https://login.microsoftonline.com/" + tenantId
            + "/oauth2/v2.0/authorize"
            + "?client_id="     + clientId
            + "&response_type=code"
            + "&redirect_uri="  + redirectUri
            + "&scope="         + scope
            + "&prompt=consent";
        }
